export const TRACKS: Track[] = TRACKS_RAW.map((t) => ({
  ...t,
  cover: TRACK_COVER[t.id] || "",
}));

export type Difficulty = "Easy" | "Medium" | "Hard" | "Expert" | "Impossible";
export const ROUND_ORDER: Difficulty[] = ["Easy", "Medium", "Hard", "Expert", "Impossible"];
export const DURATIONS: Record<Difficulty, number[]> = {
  Easy: [1, 2, 4, 7, 11, 16],
  Medium: [0.7, 1.2, 2.0, 3.5, 5.5, 8.0],
  Hard: [0.5, 0.8, 1.3, 2.0, 3.0, 4.0],
  Expert: [0.3, 0.5, 0.8, 1.3, 2.0, 3.0],
  Impossible: [0.1, 0.2, 0.35, 0.6, 1.0, 2.0],
};

export function pickRoundSongs(): Track[] {
  const pool = [...TRACKS];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, ROUND_ORDER.length);
}

export function fmtDuration(s: number): string {
  return (s % 1 === 0 ? s.toFixed(1) : s.toString()) + "s";
}